# "Build from a blank file" labs. Appended to the end of existing gym levels so earlier lab ids and saved progress do not move.
# Each one asks for a small whole (a class or two functions) with only a behaviour spec, tested against fake dependencies that fail on purpose.
def _g(k):
    return next(x for x in GYMS if x["key"] == k)

# ---------------- AI Engineering Gym ----------------
G = _g("ai")
PL(G, 3, "Build: a resilient LLM client", "Build the class <code>LLMClient(raw, retries=3, fallback=None)</code> with a method <code>ask_json(prompt)</code> that returns a dict. <code>raw(prompt)</code> is the model call: it returns text, and it can raise errors (timeouts, rate limits). Behaviour: make at most <code>retries</code> calls to <code>raw</code>. A call that raises is a failed try. A reply counts as good only if the text between its first <code>{</code> and last <code>}</code> is valid JSON (models often wrap JSON in chat); return that dict at once. A reply that is not good is a failed try, and the next try sends the original prompt plus a new line <code>Return only valid JSON.</code>. Keep <code>calls</code> (number of raw calls made) and <code>errors</code> (one entry per failed try: <code>'error: ' + message</code> for a raised error, <code>'bad json'</code> for a bad reply). When every try failed return <code>fallback</code> if it is not None, otherwise raise <code>ValueError('llm failed')</code>.", "LLMClient",
 "import json\nclass LLMClient:\n    def __init__(self, raw, retries=3, fallback=None):\n        self.raw = raw\n        self.retries = retries\n        self.fallback = fallback\n        self.calls = 0\n        self.errors = []\n    def ask_json(self, prompt):\n        p = prompt\n        for _ in range(self.retries):\n            self.calls += 1\n            try:\n                reply = self.raw(p)\n            except Exception as e:\n                self.errors.append('error: ' + str(e))\n                continue\n            try:\n                return json.loads(reply[reply.index('{'):reply.rindex('}') + 1])\n            except ValueError:\n                pass\n            self.errors.append('bad json')\n            p = prompt + '\\nReturn only valid JSON.'\n        if self.fallback is not None:\n            return self.fallback\n        raise ValueError('llm failed')\n",
 [("clean reply", "_run(['{\"a\": 1}'])"), ("JSON wrapped in chat", "_run(['Sure! Here you go: {\"a\": 2} Hope that helps.'])"), ("retries after a timeout", "_run([TimeoutError('slow'), '{\"ok\": true}'])"), ("bad JSON gets a reminder on the retry", "_run(['not json', '{\"x\": 1}'])"), ("two objects in one reply is bad JSON", "_run(['{\"a\": 1} and {\"b\": 2}', '{\"y\": 2}'])"), ("all tries fail: fallback", "_run(['no', 'no', 'no'], fallback={'safe': 1})"), ("all tries fail: error", "_run(['no', TimeoutError('t'), 'no'])"), ("retries limit the calls", "_run(['no'] * 10, retries=2, fallback={})")],
 ["Loop up to retries times, counting each raw call", "Wrap the call in try/except and record the error text", "Take the text from the first { to the last } and json.loads it", "On a bad reply record 'bad json' and change the prompt for the next try", "After the loop return the fallback or raise"], "Two things can fail inside a try: the call itself, and reading its reply. Handle both, record both, then loop again.",
 starter="class LLMClient:\n    def __init__(self, raw, retries=3, fallback=None):\n        pass\n\n    def ask_json(self, prompt):\n        pass\n",
 prelude="def _run(script, retries=3, fallback=None):\n    items = list(script)\n    seen = []\n    def raw(prompt):\n        seen.append(prompt)\n        item = items.pop(0) if items else 'no'\n        if isinstance(item, Exception):\n            raise item\n        return item\n    c = LLMClient(raw, retries=retries, fallback=fallback)\n    try:\n        out = c.ask_json('Give JSON')\n    except ValueError as e:\n        out = 'raised ' + str(e)\n    return (out, c.calls, c.errors, seen[-1])\n")

PL(G, 4, "Build: a mini RAG pipeline", "Build two functions. <b>1.</b> <code>build_index(docs, size=8, overlap=2)</code>: <code>docs</code> maps a document id to its text. Split each text on whitespace into words and cut chunks of <code>size</code> words; each new chunk starts <code>size - overlap</code> words after the previous one; stop after the chunk that reaches the end (no chunk made only of words already used). Return a list of <code>(doc_id, chunk_text)</code> in document order, chunk text joined with single spaces. <b>2.</b> <code>answer(question, index, llm, min_overlap=0.4, k=2)</code>: score each chunk as the share of the question's distinct words (lower-case letters and digits only) that appear in the chunk; keep chunks scoring at least <code>min_overlap</code>; take the best <code>k</code> (ties: earlier chunk first). If none, return <code>{'answer': \"I don't know\", 'sources': []}</code> and do not call <code>llm</code>. Otherwise call <code>llm(prompt)</code> once with a prompt containing the question and the text of every chosen chunk, and return <code>{'answer': reply, 'sources': doc ids of the chosen chunks, best first, no repeats}</code>.", "answer",
 "import re\ndef words_of(text):\n    return re.findall(r'[a-z0-9]+', text.lower())\ndef build_index(docs, size=8, overlap=2):\n    index = []\n    step = max(1, size - overlap)\n    for doc_id in docs:\n        words = docs[doc_id].split()\n        start = 0\n        while start < len(words):\n            index.append((doc_id, ' '.join(words[start:start + size])))\n            if start + size >= len(words):\n                break\n            start += step\n    return index\ndef answer(question, index, llm, min_overlap=0.4, k=2):\n    q = set(words_of(question))\n    scored = []\n    for pos, (doc_id, text) in enumerate(index):\n        score = len(q & set(words_of(text))) / len(q) if q else 0\n        if score >= min_overlap:\n            scored.append((-score, pos, doc_id, text))\n    scored.sort()\n    top = scored[:k]\n    if not top:\n        return {'answer': \"I don't know\", 'sources': []}\n    prompt = 'Answer only from the context.\\n' + '\\n'.join('[%s] %s' % (d, t) for _, _, d, t in top) + '\\nQuestion: ' + question\n    reply = llm(prompt)\n    sources = []\n    for _, _, d, _t in top:\n        if d not in sources:\n            sources.append(d)\n    return {'answer': reply, 'sources': sources}\n",
 [("chunks with overlap", "build_index({'a': 'one two three four five six seven'}, 4, 1)"), ("short text is one chunk", "build_index({'a': 'one two'}, 4, 1)"), ("two documents in order", "build_index({'x': 'a b c', 'y': 'd e f'}, 5, 1)"), ("finds the refund policy", "_ask('how are refunds paid back')"), ("finds shipping", "_ask('is shipping free')"), ("nothing relevant: no model call", "_ask('what is the moon made of')"), ("prompt holds question and context", "_prompt_check()"), ("sources have no repeats", "_ask('refunds approval days card', k=3)[0]['sources']"), ("best score wins over earlier position", "_rank()")],
 ["build_index: slide a window over the words, step = size - overlap", "Stop after the chunk that reaches the end", "answer: score = shared question words / question words", "Sort best first, ties by position, keep k", "No chunks left: return the don't-know answer before calling llm"], "Build and test build_index on its own first, then write answer on top of it.",
 starter="def build_index(docs, size=8, overlap=2):\n    pass\n\n\ndef answer(question, index, llm, min_overlap=0.4, k=2):\n    pass\n",
 prelude="DOCS = {'refunds': 'Refunds are paid back to your card within 5 business days of approval', 'shipping': 'Standard shipping is free for orders above 50 dollars', 'security': 'We never ask for your password by email or phone'}\ndef _llm_stub(prompt):\n    return 'ANSWER'\ndef _ask(q, k=2):\n    calls = []\n    def llm(p):\n        calls.append(p)\n        return 'ANSWER'\n    out = answer(q, build_index(DOCS, 8, 2), llm, k=k)\n    return (out, len(calls))\ndef _rank():\n    idx = [('a', 'red green blue'), ('b', 'blue yellow red')]\n    out = answer('blue yellow', idx, lambda p: 'x', min_overlap=0.4)\n    return out['sources']\ndef _prompt_check():\n    seen = []\n    def llm(p):\n        seen.append(p)\n        return 'x'\n    answer('is shipping free', build_index(DOCS, 8, 2), llm)\n    return (len(seen), 'is shipping free' in seen[0], 'Standard shipping is free' in seen[0])\n")

PL(G, 4, "Build: a guarded agent", "Build the class <code>Agent(llm, tools, max_steps=4, max_cost=1.0)</code> with <code>run(question)</code>. <code>tools</code> maps a name to <code>{'fn': function, 'args': {argument_name: type}, 'cost': number}</code>. Keep a history that starts as <code>[{'role': 'user', 'content': question}]</code>. Up to <code>max_steps</code> times call <code>llm(history)</code>; it returns <code>{'final': text}</code> or <code>{'tool': name, 'args': {...}}</code>. A final answer ends the run. For a tool request, decide the <b>status</b>: <code>'unknown tool'</code> if the name is not in tools; <code>'bad args'</code> if the given args do not have exactly the tool's argument names with values of the right types (the tool is NOT called and costs nothing); <code>'budget'</code> if running it would push the total cost above <code>max_cost</code> (stop the whole run now, answer <code>'stopped: budget'</code>, tool not called); otherwise call <code>fn(**args)</code>: status <code>'ok'</code>, or <code>'error'</code> if it raised. A tool that ran adds its cost to the total, even when it raised. Add each step except the budget stop to history as <code>{'role': 'tool', 'name': name, 'content': observation}</code> where the observation is <code>str(result)</code>, <code>'error: ' + message</code>, <code>'error: unknown tool ' + name</code> or <code>'error: bad args'</code>. Every tool request adds <code>(step_number, name, status)</code> to a trace (steps count from 1). Return <code>{'answer': text, 'trace': trace, 'cost': total_cost}</code>. After max_steps without a final answer the answer is <code>'stopped: too many steps'</code>.", "Agent",
 "class Agent:\n    def __init__(self, llm, tools, max_steps=4, max_cost=1.0):\n        self.llm = llm\n        self.tools = tools\n        self.max_steps = max_steps\n        self.max_cost = max_cost\n    def run(self, question):\n        history = [{'role': 'user', 'content': question}]\n        trace = []\n        cost = 0.0\n        for step in range(1, self.max_steps + 1):\n            move = self.llm(history)\n            if 'final' in move:\n                return {'answer': move['final'], 'trace': trace, 'cost': cost}\n            name = move.get('tool')\n            args = move.get('args', {})\n            tool = self.tools.get(name)\n            if tool is None:\n                status, obs = 'unknown tool', 'error: unknown tool ' + str(name)\n            elif set(args) != set(tool['args']) or not all(isinstance(args[a], tool['args'][a]) for a in args):\n                status, obs = 'bad args', 'error: bad args'\n            elif cost + tool['cost'] > self.max_cost:\n                trace.append((step, name, 'budget'))\n                return {'answer': 'stopped: budget', 'trace': trace, 'cost': cost}\n            else:\n                try:\n                    obs, status = str(tool['fn'](**args)), 'ok'\n                except Exception as e:\n                    obs, status = 'error: ' + str(e), 'error'\n                cost += tool['cost']\n            trace.append((step, name, status))\n            history.append({'role': 'tool', 'name': str(name), 'content': obs})\n        return {'answer': 'stopped: too many steps', 'trace': trace, 'cost': cost}\n",
 [("answers directly", "_agent([{'final': 'hi'}])"), ("uses a tool then answers", "_agent([{'tool': 'add', 'args': {'a': 2, 'b': 3}}, {'final': 'five'}])"), ("unknown tool", "_agent([{'tool': 'nope', 'args': {}}, {'final': 'ok'}])"), ("wrong argument type is not run", "_agent([{'tool': 'add', 'args': {'a': '2', 'b': 3}}, {'final': 'ok'}])"), ("missing argument is not run", "_agent([{'tool': 'add', 'args': {'a': 2}}, {'final': 'ok'}])"), ("tool error is reported and still costs", "_agent([{'tool': 'boom', 'args': {}}, {'final': 'handled'}])"), ("budget stops the run", "_agent([{'tool': 'add', 'args': {'a': 1, 'b': 1}}, {'tool': 'add', 'args': {'a': 1, 'b': 1}}, {'tool': 'add', 'args': {'a': 1, 'b': 1}}, {'final': 'never'}], max_cost=0.75)"), ("step limit", "_agent([{'tool': 'add', 'args': {'a': 1, 'b': 1}}], max_steps=2)"), ("the model sees the observation", "_last_seen()")],
 ["Create history, trace and cost, then loop over step numbers", "Look the tool up; decide unknown tool, bad args or budget before running anything", "Run the tool in try/except and add its cost", "Record the trace entry and the history observation", "After the loop return the step-limit answer"], "Decide the status first, with the cheapest checks first. Only the ok and error paths actually run the tool.",
 starter="class Agent:\n    def __init__(self, llm, tools, max_steps=4, max_cost=1.0):\n        pass\n\n    def run(self, question):\n        pass\n",
 prelude="import copy\ndef _boom():\n    raise RuntimeError('boom')\nTOOLS = {'add': {'fn': lambda a, b: a + b, 'args': {'a': int, 'b': int}, 'cost': 0.25}, 'boom': {'fn': _boom, 'args': {}, 'cost': 0.5}}\ndef _script(steps):\n    items = list(steps)\n    def llm(history):\n        llm.seen.append(copy.deepcopy(history))\n        return items.pop(0) if len(items) > 1 else items[0]\n    llm.seen = []\n    return llm\ndef _agent(steps, max_steps=4, max_cost=1.0):\n    return Agent(_script(steps), TOOLS, max_steps=max_steps, max_cost=max_cost).run('q')\ndef _last_seen():\n    llm = _script([{'tool': 'add', 'args': {'a': 2, 'b': 3}}, {'final': 'x'}])\n    Agent(llm, TOOLS).run('q')\n    return llm.seen[-1][-1]\n")

PL(G, 5, "Build: an eval harness", "Build <code>run_eval(cases, system)</code>. <code>cases</code> is a list of <code>{'id': ..., 'input': ..., 'expect': ..., 'tag': ...}</code>; <code>system(input)</code> returns the output. A case passes when the output, trimmed and lower-cased, equals the expected text, trimmed and lower-cased. If <code>system</code> raises, that case fails (do not stop the run). Return a dict: <code>'passed'</code> and <code>'total'</code> (counts), <code>'rate'</code> (passed / total rounded to 2 places, 0.0 when there are no cases), <code>'by_tag'</code> (tag to <code>[passed, total]</code>, tags in order of first appearance) and <code>'failures'</code> (the ids of failed cases in order).", "run_eval",
 "def run_eval(cases, system):\n    passed = 0\n    by_tag = {}\n    failures = []\n    for c in cases:\n        try:\n            ok = str(system(c['input'])).strip().lower() == str(c['expect']).strip().lower()\n        except Exception:\n            ok = False\n        t = by_tag.setdefault(c['tag'], [0, 0])\n        t[1] += 1\n        if ok:\n            passed += 1\n            t[0] += 1\n        else:\n            failures.append(c['id'])\n    total = len(cases)\n    return {'passed': passed, 'total': total, 'rate': round(passed / total, 2) if total else 0.0, 'by_tag': by_tag, 'failures': failures}\n",
 [("mixed results", "run_eval(CASES, SYSTEM)"), ("no cases", "run_eval([], SYSTEM)"), ("a crash is a failure, not a stop", "run_eval([{'id': 1, 'input': 'boom', 'expect': 'x', 'tag': 'a'}, {'id': 2, 'input': 'hi', 'expect': 'HI', 'tag': 'a'}], SYSTEM)"), ("all pass", "run_eval(CASES[:1], SYSTEM)")],
 ["Loop over the cases, calling the system inside try/except", "Compare trimmed lower-case text", "Update the per-tag counts and the failure list", "Build the summary dict at the end"], "dict.setdefault(tag, [0, 0]) gives you the counter pair for a tag, creating it on first sight.",
 starter="def run_eval(cases, system):\n    pass\n",
 prelude="def SYSTEM(text):\n    if text == 'boom':\n        raise RuntimeError('crash')\n    return ' ' + text.upper() + ' ' if text != 'two' else '3'\nCASES = [{'id': 'a1', 'input': 'hi', 'expect': 'HI', 'tag': 'greeting'}, {'id': 'a2', 'input': 'two', 'expect': '2', 'tag': 'math'}, {'id': 'a3', 'input': 'yo', 'expect': 'yo', 'tag': 'greeting'}, {'id': 'a4', 'input': 'boom', 'expect': 'x', 'tag': 'math'}]\n")

# ---------------- Field Gym (level 4: build the glue) ----------------
G = _g("fde")
PL(G, 4, "Build: a small orders API", "Build <code>handle(db, method, path, body=None, headers=None)</code> that returns <code>(status, json_dict)</code>. <code>db</code> is a dict <code>{'orders': {}, 'next_id': 1, 'keys': {}}</code> you update in place. Routes: <b>POST /orders</b> with body <code>{'item': text, 'qty': whole number}</code>: item must be non-empty text (after trimming) and qty an int above 0 (a bool is not valid). If either is invalid return <code>422</code> with <code>{'errors': [...]}</code> listing the bad field names in the order item, qty. Otherwise create the order <code>{'id', 'item' (trimmed), 'qty'}</code> with the next id, and return <code>201</code> with it. If the header <code>Idempotency-Key</code> was already used, return the exact same response as the first time and create nothing. <b>GET /orders</b>: <code>200</code> with <code>{'orders': [...]}</code> sorted by id. <b>GET /orders/&lt;id&gt;</code>: <code>200</code> with the order, or <code>404</code> <code>{'error': 'not found'}</code> (also for an id that is not a number). A known path with the wrong method: <code>405</code> <code>{'error': 'method not allowed'}</code>. Any other path: <code>404</code> <code>{'error': 'no such route'}</code>.", "handle",
 "def handle(db, method, path, body=None, headers=None):\n    headers = headers or {}\n    parts = [p for p in path.strip('/').split('/') if p]\n    if parts == ['orders']:\n        if method == 'GET':\n            return 200, {'orders': [db['orders'][i] for i in sorted(db['orders'])]}\n        if method != 'POST':\n            return 405, {'error': 'method not allowed'}\n        key = headers.get('Idempotency-Key')\n        if key in db['keys']:\n            return db['keys'][key]\n        body = body or {}\n        bad = []\n        item = body.get('item')\n        if not isinstance(item, str) or not item.strip():\n            bad.append('item')\n        q = body.get('qty')\n        if not isinstance(q, int) or isinstance(q, bool) or q <= 0:\n            bad.append('qty')\n        if bad:\n            return 422, {'errors': bad}\n        order = {'id': db['next_id'], 'item': item.strip(), 'qty': q}\n        db['orders'][order['id']] = order\n        db['next_id'] += 1\n        resp = (201, order)\n        if key:\n            db['keys'][key] = resp\n        return resp\n    if len(parts) == 2 and parts[0] == 'orders':\n        if method != 'GET':\n            return 405, {'error': 'method not allowed'}\n        if parts[1].isdigit() and int(parts[1]) in db['orders']:\n            return 200, db['orders'][int(parts[1])]\n        return 404, {'error': 'not found'}\n    return 404, {'error': 'no such route'}\n",
 [("create an order", "handle(_db(), 'POST', '/orders', {'item': ' pen ', 'qty': 3})"), ("bad qty", "handle(_db(), 'POST', '/orders', {'item': 'pen', 'qty': 0})"), ("both fields bad", "handle(_db(), 'POST', '/orders', {'item': '  ', 'qty': True})"), ("missing body", "handle(_db(), 'POST', '/orders')"), ("ids count up and list is sorted", "_two_then_list()"), ("get one", "_one_then_get(1)"), ("get missing", "_one_then_get(7)"), ("get a non-number", "_one_then_get('abc')"), ("same Idempotency-Key makes one order", "_idempotent()"), ("wrong method", "handle(_db(), 'DELETE', '/orders')"), ("wrong method on one order", "handle(_db(), 'POST', '/orders/1')"), ("unknown path", "handle(_db(), 'GET', '/users')")],
 ["Split the path into parts and route on them", "Validate the body and collect bad field names", "Create the order, update next_id, remember the response for the key", "Return the right 404/405 for everything else"], "Write the routing skeleton first (return 404 for everything), then add one route at a time and run the checks.",
 starter="def handle(db, method, path, body=None, headers=None):\n    pass\n",
 prelude="def _db():\n    return {'orders': {}, 'next_id': 1, 'keys': {}}\ndef _two_then_list():\n    d = _db()\n    handle(d, 'POST', '/orders', {'item': 'a', 'qty': 1})\n    handle(d, 'POST', '/orders', {'item': 'b', 'qty': 2})\n    return handle(d, 'GET', '/orders')\ndef _one_then_get(i):\n    d = _db()\n    handle(d, 'POST', '/orders', {'item': 'a', 'qty': 1})\n    return handle(d, 'GET', '/orders/' + str(i))\ndef _idempotent():\n    d = _db()\n    h = {'Idempotency-Key': 'k1'}\n    r1 = handle(d, 'POST', '/orders', {'item': 'a', 'qty': 1}, h)\n    r2 = handle(d, 'POST', '/orders', {'item': 'a', 'qty': 1}, h)\n    r3 = handle(d, 'POST', '/orders', {'item': 'b', 'qty': 1})\n    return (r1 == r2, r3[1]['id'], len(d['orders']))\n")

PL(G, 4, "Build: fetch every page, politely", "Build <code>fetch_all(get_page, max_waits=3, sleep=None)</code>. <code>get_page(cursor)</code> returns <code>{'items': [...], 'next': cursor_or_None}</code>; start with cursor <code>None</code> and follow <code>next</code> until it is None. Items are dicts with an <code>'id'</code>; pages can overlap, so return each id only once (first copy wins), in the order first seen. <code>get_page</code> may raise <code>RateLimited</code> (provided; it has <code>retry_after</code> seconds): call <code>sleep(retry_after)</code> and ask for the <b>same</b> cursor again. After <code>max_waits</code> rate-limit errors in a row for one page, let the error propagate. A successful page resets that count.", "fetch_all",
 "def fetch_all(get_page, max_waits=3, sleep=None):\n    out, seen = [], set()\n    cursor = None\n    waits = 0\n    while True:\n        try:\n            page = get_page(cursor)\n        except RateLimited as e:\n            waits += 1\n            if waits >= max_waits:\n                raise\n            sleep(e.retry_after)\n            continue\n        waits = 0\n        for item in page['items']:\n            if item['id'] not in seen:\n                seen.add(item['id'])\n                out.append(item)\n        cursor = page['next']\n        if cursor is None:\n            return out\n",
 [("follows every page", "_ids(_pages([[1, 2], [3, 4], [5]]))"), ("overlapping pages are de-duplicated", "_ids(_pages([[1, 2], [2, 3], [3, 4]]))"), ("waits and retries the same cursor", "_limited(1)"), ("gives up after repeated limits", "_limited(5)"), ("a good page resets the count", "_limited_twice_apart()"), ("empty first page", "_ids(_pages([[]]))")],
 ["Loop until next is None", "Catch RateLimited around the call, sleep, and try the same cursor again", "Count consecutive waits; re-raise at the limit", "Skip ids you already have"], "A bare 'raise' inside except re-raises the error you just caught.",
 starter="def fetch_all(get_page, max_waits=3, sleep=None):\n    pass\n",
 prelude="class RateLimited(Exception):\n    def __init__(self, retry_after):\n        self.retry_after = retry_after\ndef _pages(lists):\n    def get_page(cursor):\n        i = 0 if cursor is None else cursor\n        nxt = i + 1 if i + 1 < len(lists) else None\n        return {'items': [{'id': n} for n in lists[i]], 'next': nxt}\n    return get_page\ndef _ids(get_page):\n    return [x['id'] for x in fetch_all(get_page, sleep=lambda s: None)]\ndef _limited(times):\n    base = _pages([[1], [2]])\n    left = [times]\n    slept = []\n    def get_page(cursor):\n        if cursor == 1 and left[0] > 0:\n            left[0] -= 1\n            raise RateLimited(2)\n        return base(cursor)\n    try:\n        out = [x['id'] for x in fetch_all(get_page, sleep=slept.append)]\n    except RateLimited:\n        out = 'gave up'\n    return (out, slept)\ndef _limited_twice_apart():\n    base = _pages([[1], [2], [3]])\n    hits = {0: 2, 1: 2, 2: 2}\n    def get_page(cursor):\n        k = 0 if cursor is None else cursor\n        if hits[k] > 0 and k < 3:\n            hits[k] -= 1\n            raise RateLimited(1)\n        return base(cursor)\n    return [x['id'] for x in fetch_all(get_page, max_waits=3, sleep=lambda s: None)]\n")

# ---------------- Deployment Gym (level 2: containers) ----------------
G = _g("dep")
_DEPPRE = "import json\ndef parse_dockerfile(text):\n    out = []\n    cur = ''\n    for raw in text.splitlines():\n        line = raw.strip()\n        if not cur and (not line or line.startswith('#')):\n            continue\n        if line.endswith('\\\\'):\n            cur += line[:-1].strip() + ' '\n            continue\n        cur += line\n        parts = cur.strip().split(None, 1)\n        out.append((parts[0].upper(), parts[1].strip() if len(parts) > 1 else ''))\n        cur = ''\n    return out\ndef lint_dockerfile(text):\n    ins = parse_dockerfile(text)\n    names = [i for i, _ in ins]\n    found = set()\n    for i, a in ins:\n        if i == 'FROM':\n            img = a.split()[0]\n            if img != 'scratch' and '@sha256' not in img:\n                last = img.rsplit('/', 1)[-1]\n                if ':' not in last or last.endswith(':latest'):\n                    found.add('unpinned-base')\n        if i == 'ENV' and any(w in a.upper() for w in ('PASSWORD', 'SECRET', 'TOKEN')):\n            found.add('secret-in-env')\n    if 'USER' not in names:\n        found.add('runs-as-root')\n    if 'ADD' in names:\n        found.add('uses-add')\n    if 'HEALTHCHECK' not in names:\n        found.add('no-healthcheck')\n    return sorted(found)\ndef cache_friendly(text):\n    ins = parse_dockerfile(text)\n    dep = whole = None\n    for n, (i, a) in enumerate(ins):\n        if i == 'COPY':\n            if dep is None and any(w in a for w in ('requirements', 'package.json', 'pyproject')):\n                dep = n\n            if whole is None and a.startswith('. '):\n                whole = n\n    if dep is None or whole is None or dep > whole:\n        return False\n    return any(i == 'RUN' and 'install' in a for i, a in ins[dep:whole])\n"
PL(G, 2, "Build: a Dockerfile that passes your own checks", "Build <code>make_dockerfile(base, port, cmd, deps='requirements.txt')</code> for a Python web service and return the file text. <code>base</code> is the base image, <code>port</code> the port, <code>cmd</code> a list such as <code>['uvicorn', 'app:app']</code>. If <code>base</code> has no tag or ends in <code>:latest</code> raise <code>ValueError('pin the base image')</code>. The file you build must pass the checks from the earlier labs (<code>parse_dockerfile</code>, <code>lint_dockerfile</code> and <code>cache_friendly</code> are provided): no lint problems at all (non-root <code>USER</code>, a <code>HEALTHCHECK</code>, no <code>ADD</code>, no secrets), dependencies installed before the app code is copied, <code>EXPOSE</code> the port, and start with <code>CMD</code> in the JSON list form. End the text with a newline.", "make_dockerfile",
 "import json\ndef make_dockerfile(base, port, cmd, deps='requirements.txt'):\n    last = base.rsplit('/', 1)[-1]\n    if ':' not in last or last.endswith(':latest'):\n        raise ValueError('pin the base image')\n    return '\\n'.join(['FROM ' + base, 'WORKDIR /app', 'COPY ' + deps + ' .', 'RUN pip install --no-cache-dir -r ' + deps, 'COPY . .', 'RUN useradd --create-home app', 'USER app', 'EXPOSE ' + str(port), 'HEALTHCHECK CMD curl -f http://localhost:%d/health || exit 1' % port, 'CMD ' + json.dumps(cmd)]) + '\\n'\n",
 [("no lint problems", "lint_dockerfile(make_dockerfile('python:3.12-slim', 8000, ['uvicorn', 'app:app']))"), ("dependencies cached before code", "cache_friendly(make_dockerfile('python:3.12-slim', 8000, ['uvicorn', 'app:app']))"), ("starts from the base given", "_first('registry.local/py:3.11')"), ("exposes the port", "_has('EXPOSE', '9090')"), ("CMD is a JSON list", "_cmd()"), ("uses the deps file name given", "_deps()"), ("unpinned base is refused", "_refused('python')"), ("latest is refused", "_refused('python:latest')"), ("ends with a newline", "make_dockerfile('python:3.12', 1, ['x']).endswith('\\n')")],
 ["Check the base image first", "Order matters: copy the deps file, install, then copy everything", "Add USER, EXPOSE and HEALTHCHECK so the linter is happy", "Write CMD with json.dumps(cmd)"], "Run your own lint_dockerfile on the result as you work; it tells you what is missing.",
 starter="def make_dockerfile(base, port, cmd, deps='requirements.txt'):\n    pass\n",
 prelude=_DEPPRE + "def _first(base):\n    return parse_dockerfile(make_dockerfile(base, 80, ['x']))[0]\ndef _has(ins, arg):\n    return any(i == ins and arg in a for i, a in parse_dockerfile(make_dockerfile('python:3.12', int(arg), ['x'])))\ndef _cmd():\n    ins = parse_dockerfile(make_dockerfile('python:3.12', 80, ['uvicorn', 'app:app', '--port', '80']))\n    cmds = [a for i, a in ins if i == 'CMD']\n    return (len(cmds), json.loads(cmds[0]) if cmds else None)\ndef _deps():\n    ins = parse_dockerfile(make_dockerfile('python:3.12', 80, ['x'], deps='reqs/prod.txt'))\n    return [a for i, a in ins if i in ('COPY', 'RUN')][:2]\ndef _refused(base):\n    try:\n        make_dockerfile(base, 80, ['x'])\n    except ValueError as e:\n        return str(e)\n    return 'accepted'\n")

# ---------------- Python Gym (level 5: write code others can use) ----------------
G = _g("py")
_PDRAW = "import pandas as pd\nRAW = pd.DataFrame({'order_id': [1, 2, 3, 3, 4, 5, 6, 7], 'date': ['2026-01-05', '2026-01-20', '2026-02-02', '2026-02-02', 'not a date', '2026-02-10', '2026-02-11', '2026-01-31'], 'city': [' pune', 'PUNE ', 'delhi', 'Delhi', 'Pune', 'delhi', 'Delhi', ' Pune '], 'amount': ['1,200.50', '99', '250', '999', '10', '', 'abc', '300.25']})\n"
PL(G, 5, "Build: a monthly report from a messy export", "Build <code>monthly_report(raw)</code> for a pandas DataFrame <code>RAW</code> with columns <code>order_id</code>, <code>date</code> (text like <code>2026-01-05</code>), <code>city</code> and <code>amount</code> (text, may have thousands commas, may be empty or garbage). Steps in this order: tidy <code>city</code> (trim spaces, Title Case); turn <code>amount</code> into numbers (remove commas; anything that is not a number becomes missing) and <code>date</code> into dates (anything that is not a date becomes missing); drop rows where amount or date is missing; then drop repeated <code>order_id</code> keeping the first; add <code>month</code> as text like <code>2026-01</code>. Return one row per month and city with columns <code>month</code>, <code>city</code>, <code>orders</code> (count) and <code>revenue</code> (sum of amount rounded to 2 places), sorted by month then city, with a fresh index. Do not change the DataFrame that was passed in.", "monthly_report",
 "import pandas as pd\ndef monthly_report(raw):\n    df = raw.copy()\n    df['city'] = df['city'].str.strip().str.title()\n    df['amount'] = pd.to_numeric(df['amount'].astype(str).str.replace(',', '', regex=False), errors='coerce')\n    df['date'] = pd.to_datetime(df['date'], errors='coerce', format='%Y-%m-%d')\n    df = df.dropna(subset=['amount', 'date'])\n    df = df.drop_duplicates(subset='order_id', keep='first')\n    df['month'] = df['date'].dt.strftime('%Y-%m')\n    out = df.groupby(['month', 'city']).agg(orders=('order_id', 'count'), revenue=('amount', 'sum')).reset_index()\n    out['revenue'] = out['revenue'].round(2)\n    return out.sort_values(['month', 'city']).reset_index(drop=True)\n",
 [("the report", "monthly_report(RAW).to_dict('records')"), ("columns and order", "list(monthly_report(RAW).columns)"), ("bad rows and repeats are gone", "int(monthly_report(RAW)['orders'].sum())"), ("input is left alone", "_untouched()"), ("a clean frame with one row", "monthly_report(pd.DataFrame({'order_id': [1], 'date': ['2026-03-01'], 'city': ['goa'], 'amount': ['5']})).to_dict('records')"), ("index starts at 0", "list(monthly_report(RAW).index)")],
 ["Copy the frame, then clean city, amount and date", "Drop missing, then drop duplicate order ids", "Make the month text with the dt accessor", "groupby month and city, then agg count and sum", "Round, sort and reset the index"], "Do the cleaning steps one line at a time and print the frame after each, as you would on real data.",
 starter="import pandas as pd\n\ndef monthly_report(raw):\n    pass\n", prelude=_PDRAW + "def _untouched():\n    before = RAW['city'].tolist(), RAW['amount'].tolist(), list(RAW.columns)\n    monthly_report(RAW)\n    return before == (RAW['city'].tolist(), RAW['amount'].tolist(), list(RAW.columns))\n", kw=dict(pkgs=True))
